outputs.prompt:
Quadrilateral $ABCD$ is formed by four tangents to circle $O$, with $AB$ parallel to $CD$. Find $\angle AOC$.

[asy]
import graph;

unitsize(1.5 cm);

pair A, B, O, C, D, R, S, T, U;

R = dir(115);
S = dir(230);
T = dir(270);
U = dir(65);
A = extension(R, R + rotate(90)*(R), T, T + rotate(90)*(T));
B = extension(S, S + rotate(90)*(S), T, T + rotate(90)*(T));
C = extension(R, R + rotate(90)*(R), U, U + rotate(90)*(U));
D = extension(S, S + rotate(90)*(S), U, U + rotate(90)*(U));

draw(Circle((0,0),1));
draw((R + 0.1*(R - C))--C--(U + 0.1*(U - C)));
draw((S + 0.1*(S - D))--D--(U + 0.1*(U - D)));
draw((R + 0.1*(R - A))--A--(T + 0.1*(T - A)));
draw((S + 0.1*(S - B))--B--(T + 0.1*(T - B)));

label("$A$", A, dir(270));
label("$B$", B, NW);
label("$O$", O, NE);
label("$C$", C, N);
label("$D$", D, NE);
label("$R$", R, NW);
label("$S$", S, NE);
label("$T$", T, dir(270));
label("$U$", U, NE);
[/asy]
